// Formula parser and evaluator. AST nodes: num, str, bool, ref, range, unary, bin, call.
import { parseAddr, toAddr } from "./addr.mjs";

const isErr = (v) => typeof v === "string" && v.startsWith("#");
const NUM_RE = /^[+-]?(\d+\.?\d*|\.\d+)(e[+-]?\d+)?$/i;

function tokenize(text) {
  const toks = [];
  let i = 0;
  while (i < text.length) {
    const c = text[i];
    if (/\s/.test(c)) { i++; continue; }
    let m;
    if (c === '"') {
      let s = "", j = i + 1;
      for (;;) {
        if (j >= text.length) throw new SyntaxError("unterminated string");
        if (text[j] === '"') {
          if (text[j + 1] === '"') { s += '"'; j += 2; continue; }
          break;
        }
        s += text[j++];
      }
      toks.push({ t: "str", v: s });
      i = j + 1;
    } else if ((m = /^(\d+\.?\d*|\.\d+)(e[+-]?\d+)?/i.exec(text.slice(i)))) {
      toks.push({ t: "num", v: Number(m[0]) });
      i += m[0].length;
    } else if ((m = /^[A-Za-z_$][A-Za-z0-9_.$]*/.exec(text.slice(i)))) {
      toks.push({ t: "id", v: m[0] });
      i += m[0].length;
    } else if ((m = /^(<>|<=|>=|[=<>&+\-*\/^(),:])/.exec(text.slice(i)))) {
      toks.push({ t: "op", v: m[0] });
      i += m[0].length;
    } else throw new SyntaxError(`unexpected character ${c}`);
  }
  return toks;
}

const REF_RE = /^\$?[A-Za-z]{1,3}\$?[1-9]\d*$/;
const normRef = (s) => { const a = parseAddr(s); return toAddr(a.col, a.row); };

export function parseFormula(text) {
  const toks = tokenize(text);
  let p = 0;
  const peek = () => toks[p];
  const isOp = (v) => toks[p] && toks[p].t === "op" && toks[p].v === v;
  const expect = (v) => { if (!isOp(v)) throw new SyntaxError(`expected ${v}`); p++; };

  function binLevel(ops, next) {
    return () => {
      let left = next();
      while (toks[p] && toks[p].t === "op" && ops.includes(toks[p].v)) {
        const op = toks[p++].v;
        left = { type: "bin", op, left, right: next() };
      }
      return left;
    };
  }
  function unary() {
    if (isOp("-") || isOp("+")) {
      const op = toks[p++].v;
      return { type: "unary", op, arg: unary() };
    }
    return primary();
  }
  const power = binLevel(["^"], unary);
  const mul = binLevel(["*", "/"], power);
  const add = binLevel(["+", "-"], mul);
  const cat = binLevel(["&"], add);
  const cmp = binLevel(["=", "<>", "<", ">", "<=", ">="], cat);

  function primary() {
    const t = toks[p];
    if (!t) throw new SyntaxError("unexpected end");
    if (t.t === "num") { p++; return { type: "num", value: t.v }; }
    if (t.t === "str") { p++; return { type: "str", value: t.v }; }
    if (t.t === "op" && t.v === "(") {
      p++;
      const e = cmp();
      expect(")");
      return e;
    }
    if (t.t === "id") {
      p++;
      if (isOp("(")) {
        p++;
        const args = [];
        if (isOp(")")) p++;
        else {
          for (;;) {
            args.push(cmp());
            if (isOp(",")) { p++; continue; }
            expect(")");
            break;
          }
        }
        return { type: "call", name: t.v.toUpperCase(), args };
      }
      const up = t.v.toUpperCase();
      if (up === "TRUE" || up === "FALSE") return { type: "bool", value: up === "TRUE" };
      if (!REF_RE.test(t.v)) throw new SyntaxError(`unexpected name ${t.v}`);
      if (isOp(":")) {
        p++;
        const t2 = toks[p];
        if (!t2 || t2.t !== "id" || !REF_RE.test(t2.v)) throw new SyntaxError("bad range");
        p++;
        const a = parseAddr(t.v), b = parseAddr(t2.v);
        return {
          type: "range",
          c1: Math.min(a.col, b.col), c2: Math.max(a.col, b.col),
          r1: Math.min(a.row, b.row), r2: Math.max(a.row, b.row),
        };
      }
      return { type: "ref", addr: normRef(t.v) };
    }
    throw new SyntaxError(`unexpected token ${t.v}`);
  }

  const ast = cmp();
  if (p < toks.length) throw new SyntaxError(`unexpected token ${toks[p].v}`);
  return ast;
}

function rangeAddrs(n) {
  const out = [];
  for (let r = n.r1; r <= n.r2; r++) for (let c = n.c1; c <= n.c2; c++) out.push(toAddr(c, r));
  return out;
}

export function refsOf(ast) {
  const seen = new Set();
  const walk = (n) => {
    switch (n.type) {
      case "ref": seen.add(n.addr); break;
      case "range": for (const a of rangeAddrs(n)) seen.add(a); break;
      case "unary": walk(n.arg); break;
      case "bin": walk(n.left); walk(n.right); break;
      case "call": n.args.forEach(walk); break;
    }
  };
  walk(ast);
  return [...seen];
}

function toNum(v) {
  if (isErr(v)) return v;
  if (v === null) return 0;
  if (typeof v === "number") return v;
  if (typeof v === "boolean") return v ? 1 : 0;
  const s = v.trim();
  if (s !== "" && NUM_RE.test(s)) return Number(s);
  return "#VALUE!";
}

function toText(v) {
  if (v === null) return "";
  if (typeof v === "boolean") return v ? "TRUE" : "FALSE";
  return String(v);
}

function toBool(v) {
  if (isErr(v)) return v;
  if (v === null) return false;
  if (typeof v === "boolean") return v;
  if (typeof v === "number") return v !== 0;
  const u = v.trim().toUpperCase();
  if (u === "TRUE") return true;
  if (u === "FALSE") return false;
  return "#VALUE!";
}

const rank = (v) => (typeof v === "number" ? 0 : typeof v === "string" ? 1 : 2);

function compare(a, b) {
  if (a === null && b === null) return 0;
  if (a === null) a = typeof b === "number" ? 0 : typeof b === "string" ? "" : false;
  else if (b === null) b = typeof a === "number" ? 0 : typeof a === "string" ? "" : false;
  if (rank(a) !== rank(b)) return rank(a) - rank(b);
  if (typeof a === "string") { a = a.toLowerCase(); b = b.toLowerCase(); }
  return a < b ? -1 : a > b ? 1 : 0;
}

const fin = (n) => (Number.isFinite(n) ? n : "#NUM!");

function round(x, d) {
  d = Math.trunc(d);
  const abs = Math.abs(x);
  let r;
  if (String(abs).includes("e")) r = Math.round(abs * 10 ** d) / 10 ** d;
  else r = Number(Math.round(Number(`${abs}e${d}`)) + `e${-d}`);
  return (x < 0 ? -r : r) + 0;
}

export function evaluate(ast, lookup) {
  const ev = (n) => {
    switch (n.type) {
      case "num": case "str": case "bool": return n.value;
      case "ref": return lookup(n.addr);
      case "range": return "#VALUE!";
      case "unary": {
        const v = toNum(ev(n.arg));
        if (typeof v === "string") return v;
        return fin(n.op === "-" ? -v : v) + 0 === 0 ? 0 : fin(n.op === "-" ? -v : v);
      }
      case "bin": return binary(n);
      case "call": return call(n);
    }
  };

  function binary(n) {
    const l = ev(n.left);
    const r = ev(n.right);
    if (isErr(l)) return l;
    if (isErr(r)) return r;
    switch (n.op) {
      case "&": return toText(l) + toText(r);
      case "=": return compare(l, r) === 0;
      case "<>": return compare(l, r) !== 0;
      case "<": return compare(l, r) < 0;
      case ">": return compare(l, r) > 0;
      case "<=": return compare(l, r) <= 0;
      case ">=": return compare(l, r) >= 0;
    }
    const a = toNum(l);
    if (typeof a === "string") return a;
    const b = toNum(r);
    if (typeof b === "string") return b;
    switch (n.op) {
      case "+": return fin(a + b);
      case "-": return fin(a - b);
      case "*": return fin(a * b);
      case "/": return b === 0 ? "#DIV/0!" : fin(a / b);
      case "^": return fin(a ** b);
    }
  }

  // Collects arguments: ranges as lists of cell values, others as single evaluated values.
  const items = (args) => args.map((a) => (a.type === "range" ? { range: rangeAddrs(a).map(lookup) } : { v: ev(a) }));

  function numeric(name, args) {
    const nums = [];
    for (const it of items(args)) {
      if (it.range) {
        for (const v of it.range) {
          if (isErr(v)) { if (name !== "COUNT") return v; }
          else if (typeof v === "number") nums.push(v);
        }
      } else if (name === "COUNT") {
        if (typeof it.v === "number") nums.push(it.v);
      } else {
        const v = toNum(it.v);
        if (typeof v === "string") return v;
        nums.push(v);
      }
    }
    switch (name) {
      case "COUNT": return nums.length;
      case "SUM": return fin(nums.reduce((s, x) => s + x, 0));
      case "AVERAGE": return nums.length ? fin(nums.reduce((s, x) => s + x, 0) / nums.length) : "#DIV/0!";
      case "MIN": return nums.length ? Math.min(...nums) : 0;
      case "MAX": return nums.length ? Math.max(...nums) : 0;
    }
  }

  function logical(name, args) {
    if (args.length < 1) return "#VALUE!";
    let acc = name === "AND";
    for (const it of items(args)) {
      const vals = [];
      if (it.range) {
        for (const v of it.range) {
          if (isErr(v)) return v;
          if (typeof v === "number" || typeof v === "boolean") vals.push(v);
        }
      } else vals.push(it.v);
      for (const v of vals) {
        const b = toBool(v);
        if (typeof b === "string") return b;
        acc = name === "AND" ? acc && b : acc || b;
      }
    }
    return acc;
  }

  function call(n) {
    const { name, args } = n;
    const k = args.length;
    if (["SUM", "AVERAGE", "MIN", "MAX", "COUNT"].includes(name)) return numeric(name, args);
    if (name === "AND" || name === "OR") return logical(name, args);
    if (name === "CONCAT") {
      let s = "";
      for (const it of items(args)) {
        for (const v of it.range ?? [it.v]) {
          if (isErr(v)) return v;
          s += toText(v);
        }
      }
      return s;
    }
    const arity = { IF: [2, 3], NOT: [1, 1], ROUND: [2, 2], ABS: [1, 1], LEN: [1, 1], UPPER: [1, 1], LOWER: [1, 1] }[name];
    if (!arity) return "#NAME?";
    if (k < arity[0] || k > arity[1]) return "#VALUE!";
    if (name === "IF") {
      if (args[0].type === "range") return "#VALUE!";
      const c = toBool(ev(args[0]));
      if (typeof c === "string") return c;
      if (c) return args[1].type === "range" ? "#VALUE!" : ev(args[1]);
      if (k === 2) return false;
      return args[2].type === "range" ? "#VALUE!" : ev(args[2]);
    }
    const vals = args.map((a) => (a.type === "range" ? "#VALUE!" : ev(a)));
    for (const v of vals) if (isErr(v)) return v;
    switch (name) {
      case "NOT": { const b = toBool(vals[0]); return typeof b === "string" ? b : !b; }
      case "ABS": { const x = toNum(vals[0]); return typeof x === "string" ? x : Math.abs(x); }
