        const x = toNum(vals[0]);
        if (typeof x === "string") return x;
        const d = toNum(vals[1]);
        if (typeof d === "string") return d;
        return fin(round(x, d));
      }
      case "LEN": return toText(vals[0]).length;
      case "UPPER": return toText(vals[0]).toUpperCase();
      case "LOWER": return toText(vals[0]).toLowerCase();
    }
  }

  return ev(ast);
}
