import { parseFormula, refsOf, evaluate } from "./formula.mjs";
import { parseAddr, toAddr, compareAddr } from "./addr.mjs";

const NUM_RE = /^[+-]?(\d+\.?\d*|\.\d+)(e[+-]?\d+)?$/i;

export function valueOf(raw) {
  if (raw === "") return null;
  const t = raw.trim();
  if (t !== "" && NUM_RE.test(t) && Number.isFinite(Number(t))) return Number(t);
  const u = raw.toUpperCase();
  if (u === "TRUE") return true;
  if (u === "FALSE") return false;
  if (raw.startsWith("'")) return raw.slice(1);
  return raw;
}

// Parses every formula cell; returns Map addr -> { ast, refs } (ast null on syntax error).
function graph(sheet) {
  const g = new Map();
  for (const [addr, raw] of sheet.cells) {
    if (!raw.startsWith("=")) continue;
    try {
      const ast = parseFormula(raw.slice(1));
      g.set(addr, { ast, refs: refsOf(ast) });
    } catch {
      g.set(addr, { ast: null, refs: [] });
    }
  }
  return g;
}

// Iterative Tarjan. Returns SCCs, dependencies first.
function sccs(g) {
  const index = new Map(), low = new Map(), onStack = new Set(), stack = [], out = [];
  let counter = 0;
  for (const root of g.keys()) {
    if (index.has(root)) continue;
    const work = [{ v: root, i: 0 }];
    index.set(root, counter); low.set(root, counter++); stack.push(root); onStack.add(root);
    while (work.length) {
      const f = work[work.length - 1];
      const refs = g.get(f.v).refs;
      if (f.i < refs.length) {
        const w = refs[f.i++];
        if (!g.has(w)) continue;
        if (!index.has(w)) {
          index.set(w, counter); low.set(w, counter++); stack.push(w); onStack.add(w);
          work.push({ v: w, i: 0 });
        } else if (onStack.has(w)) low.set(f.v, Math.min(low.get(f.v), index.get(w)));
      } else {
        work.pop();
        if (work.length) {
          const u = work[work.length - 1].v;
          low.set(u, Math.min(low.get(u), low.get(f.v)));
        }
        if (low.get(f.v) === index.get(f.v)) {
          const comp = [];
          let w;
          do { w = stack.pop(); onStack.delete(w); comp.push(w); } while (w !== f.v);
          out.push(comp);
        }
      }
    }
  }
  return out;
}

const isCycle = (g, comp) => comp.length > 1 || g.get(comp[0]).refs.includes(comp[0]);

export function computeAll(sheet) {
  const g = graph(sheet);
  const values = new Map();
  for (const [addr, raw] of sheet.cells) if (!g.has(addr)) values.set(addr, valueOf(raw));
  const lookup = (a) => values.get(a) ?? null;
  for (const comp of sccs(g)) {
    if (isCycle(g, comp)) { for (const a of comp) values.set(a, "#CYCLE!"); continue; }
    const node = g.get(comp[0]);
    values.set(comp[0], node.ast ? evaluate(node.ast, lookup) : "#ERROR!");
  }
  const out = new Map();
  for (const addr of sheet.cells.keys()) out.set(addr, values.get(addr));
  return out;
}

export function dependents(sheet, addr) {
  const a = parseAddr(addr);
  const start = toAddr(a.col, a.row);
  const g = graph(sheet);
  const cyc = new Set();
  for (const comp of sccs(g)) if (isCycle(g, comp)) for (const x of comp) cyc.add(x);
  const rev = new Map();
  for (const [x, node] of g) for (const r of node.refs) {
    if (!rev.has(r)) rev.set(r, []);
    rev.get(r).push(x);
  }
  const set = new Set();
  const queue = [start];
  while (queue.length) {
    for (const x of rev.get(queue.pop()) ?? []) {
      if (set.has(x) || x === start || cyc.has(x)) continue;
      set.add(x);
      queue.push(x);
    }
  }
  const indeg = new Map(), outs = new Map();
  for (const x of set) {
    indeg.set(x, 0);
    outs.set(x, []);
  }
  for (const x of set) for (const r of g.get(x).refs) if (set.has(r) && r !== x) {
    indeg.set(x, indeg.get(x) + 1);
    outs.get(r).push(x);
  }
  const ready = [...set].filter((x) => indeg.get(x) === 0);
  const result = [];
  while (ready.length) {
    let best = 0;
    for (let i = 1; i < ready.length; i++) if (compareAddr(ready[i], ready[best]) < 0) best = i;
    const x = ready.splice(best, 1)[0];
    result.push(x);
    for (const y of outs.get(x)) {
      indeg.set(y, indeg.get(y) - 1);
      if (indeg.get(y) === 0) ready.push(y);
    }
  }
  return result;
}
