import { createSheet, setCell, getCell } from "./sheet.mjs";
import { parseAddr, toAddr } from "./addr.mjs";

const text = (v) => (v === null || v === undefined ? "" : typeof v === "boolean" ? (v ? "TRUE" : "FALSE") : String(v));

const quote = (s) => (/[,"\n\r]/.test(s) || s.startsWith(" ") || s.endsWith(" ") ? `"${s.replace(/"/g, '""')}"` : s);

export function toCSV(sheet, values) {
  let maxRow = -1, maxCol = -1;
  for (const addr of sheet.cells.keys()) {
    const a = parseAddr(addr);
    maxRow = Math.max(maxRow, a.row);
    maxCol = Math.max(maxCol, a.col);
  }
  let out = "";
  for (let r = 0; r <= maxRow; r++) {
    const fields = [];
    for (let c = 0; c <= maxCol; c++) {
      const addr = toAddr(c, r);
      fields.push(quote(values ? text(values.get(addr)) : getCell(sheet, addr)));
    }
    out += fields.join(",") + "\n";
  }
  return out;
}

function detectDelimiter(src) {
  const counts = { ",": 0, ";": 0, "\t": 0 };
  let inQ = false;
  for (const ch of src) {
    if (ch === '"') inQ = !inQ;
    else if (!inQ) {
      if (ch === "\n") break;
      if (ch in counts) counts[ch]++;
    }
  }
  let best = ",";
  for (const d of [";", "\t"]) if (counts[d] > counts[best]) best = d;
  return best;
}

export function fromCSV(src, options = {}) {
  const delim = options.delimiter ?? detectDelimiter(src);
  const rows = [];
  let row = [], field = "", atStart = true, line = 1, i = 0;
  const endField = () => { row.push(field); field = ""; };
  const endRow = () => { endField(); rows.push(row); row = []; atStart = true; };
  while (i < src.length) {
    const ch = src[i];
    if (ch === '"' && field === "" && atStart !== "mid") {
      const startLine = line;
      let j = i + 1;
      for (;;) {
        if (j >= src.length) throw new Error(`unclosed quote at line ${startLine}`);
        if (src[j] === '"') {
          if (src[j + 1] === '"') { field += '"'; j += 2; continue; }
          break;
        }
        if (src[j] === "\n") line++;
        field += src[j++];
      }
      i = j + 1;
      atStart = "mid";
    } else if (ch === delim) { endField(); atStart = false; i++; }
    else if (ch === "\n" || (ch === "\r" && src[i + 1] === "\n")) {
      if (ch === "\r") i++;
      i++;
      line++;
      endRow();
    } else { field += ch; atStart = "mid"; i++; }
  }
  if (!atStart || field !== "" || row.length) endRow();
  const sheet = createSheet();
  rows.forEach((r, ri) => r.forEach((f, ci) => {
    if (f === "") return;
    if (f.startsWith("=") && !options.formulas) f = "'" + f;
    setCell(sheet, toAddr(ci, ri), f);
  }));
  return sheet;
}
