  assert.deepEqual(refsOf(parseFormula("SUM($b$1:A2)+A1")), ["A1", "B1", "A2", "B2"].filter((x) => x !== "B2" || true).slice(0, 4).sort((a, b) => 0) && ["A1", "B1", "A2", "B2"]);
  assert.throws(() => parseFormula("1+"), SyntaxError);
});

test("recalc", () => {
  assert.equal(valueOf("'12"), "12");
  assert.equal(valueOf(" 4 "), 4);
  const s = mk({ A1: "=B1", B1: "=A1", C1: "=A1+1", D1: "=1+", E1: "2" });
  const v = computeAll(s);
  assert.equal(v.get("A1"), "#CYCLE!");
  assert.equal(v.get("C1"), "#CYCLE!");
  assert.equal(v.get("D1"), "#ERROR!");
  const big = createSheet();
  setCell(big, "A1", "1");
  for (let i = 2; i <= 10000; i++) setCell(big, `A${i}`, `=A${i - 1}+1`);
  assert.equal(computeAll(big).get("A10000"), 10000);
  const d = mk({ A1: "1", B1: "=A1", A2: "=B1+A1", C3: "=A2" });
  assert.deepEqual(dependents(d, "A1"), ["B1", "A2", "C3"]);
});

test("numfmt", () => {
  assert.equal(formatNumber(0.5, "#.00"), ".50");
  assert.equal(formatNumber(1.005, "0.00"), "1.01");
  assert.equal(formatNumber(2, "0.##"), "2.");
  assert.equal(formatNumber(1234567.891, "#,##0.00"), "1,234,567.89");
  assert.equal(formatNumber(0.256, "0%"), "26%");
  assert.equal(formatNumber(12345.678, "0.00E+00"), "1.23E+04");
  assert.equal(formatNumber(-5, "0;(0)"), "(5)");
